FILE *in = fopen(input_file, "r");
    if (!in) return 1;
    fseek(in, 0, SEEK_END);
    long size = ftell(in);
    fseek(in, 0, SEEK_SET);
    char *json = malloc(size + 1);
    fread(json, 1, size, in);
    json[size] = '\0';
    fclose(in);
    // Parse name from JSON
    char *name_start = strstr(json, "\"name\"");
    if (!name_start) return 1;
    name_start = strchr(name_start, ':');
    if (!name_start) return 1;
    name_start = strchr(name_start, '\"');
    if (!name_start) return 1;
    name_start++;
    char *name_end = strchr(name_start, '\"');
    if (!name_end) return 1;
    int name_len = name_end - name_start;
    char func_name[256];
    strncpy(func_name, name_start, name_len);
    func_name[name_len] = '\0';
    // Parse logic
    char *logic_start = strstr(json, "\"logic\"");
    if (!logic_start) return 1;
    logic_start = strchr(logic_start, ':');
    if (!logic_start) return 1;
    logic_start = strchr(logic_start, '\"');
    if (!logic_start) return 1;
    logic_start++;
    char *logic_end = strstr(logic_start, "\"");
    if (!logic_end) return 1;
    int logic_len = logic_end - logic_start;
    char *logic = malloc(logic_len + 1);
    strncpy(logic, logic_start, logic_len);
    logic[logic_len] = '\0';
    // Replace escaped newlines
    for (int i = 0; i < logic_len; i++) {
        if (logic[i] == 'n' && i > 0 && logic[i-1] == '\\') {
            logic[i-1] = '\n';
            for (int j = i; j < logic_len; j++) {
                logic[j-1] = logic[j];
            }
            logic_len--;
        }
    }
    // Generate output C file
    FILE *out = fopen(output_file, "w");
    if (!out) return 1;
    fprintf(out, "#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n\n");
    fprintf(out, "int %s(int n) {\n    %s\n}\n\n", func_name, logic);
    fprintf(out, "int main(int argc, char *argv[]) {\n");
    fprintf(out, "    int n = argc > 1 ? atoi(argv[1]) : 0;\n");
    fprintf(out, "    printf(\"%%d\\n\", %s(n));\n", func_name);
    fprintf(out, "    return 0;\n}\n");
    fclose(out);
    free(json);
    free(logic);
    return 0;

