#define TABLE_SIZE 100
    struct Entry { int key; int value; } table[TABLE_SIZE];
    for (int i = 0; i < TABLE_SIZE; i++) table[i].key = -1;
    // Hash function
    int hash(int key) { return key % TABLE_SIZE; }
    // Insert squares
    for (int i = 1; i <= n; i++) {
        int key = i;
        int val = i * i;
        int h = hash(key);
        while (table[h].key != -1) {
            h = (h + 1) % TABLE_SIZE;
        }
        table[h].key = key;
        table[h].value = val;
    }
    // Retrieve and display
    printf("Hash Table contents:\n");
    for (int i = 1; i <= n; i++) {
        int h = hash(i);
        while (table[h].key != i) {
            h = (h + 1) % TABLE_SIZE;
        }
        printf("  %d -> %d\n", i, table[h].value);
    }
    return 0;

